(256, 1, 'edit_content_data', 'if($_GET[\"edit_content_data\"] == \'#Enter Your Content Name#\'){\n    ob_end_clean();\n$check_url = validate_url();\nif ($check_url  == \'success\'){ \n//this is where u put the code\n\n $response_edit_content = jlon_create($response_edit_content); \n$response_edit_content -> content_header =\'Edit Your Form Object\';\n \n$response_edit_content -> content_body .= $lifetech_modal_body;\n$response_edit_content -> content_footer .= $lifetech_modal_footer;\n$response_edit_content -> content_jquery .= $lifetech_modal_jquery ;\n$response_edit_content -> echo_type_modal .= \"Yes\";\necho jlon_encode($response_edit_content);\n    exit();\n\n    }else{ \n\n$response_edit_content = jlon_create($response_edit_content);\n$response_edit_content -> content_body .= \'Your Id is not equivalent to your Pin  \'; \necho jlon_encode($response_edit_content); \nexit();\n\n\n}\n}', 'content_data', NULL, '2024-10-26 11:07:36', NULL),
